403 |               <div className={`w-2 h-2 rounded-full ${isRefreshing ? "bg-[#f4b400] animate-spin" : "bg-[#0fa336] animate-pulse"}`} />
404 |               <span className="text-[10px] font-bold uppercase tracking-wider text-[#bbb]">
