414 |               <div>
415 |                 <div className="font-bold text-[11px]">{currentWeather?.avg_temp ? Math.round(currentWeather.avg_temp) : 28}°C</div>
416 |                 <div className="text-[9px] text-[#bbbbbb]">Partly cloudy</div>
417 |               </div>
418 |             </div>
419 | 
420 |             <div className="flex items-center gap-3 border-l border-[#3c3c3c] pl-6 relative">
421 |               <button
422 |                 onClick={() => setShowNotifications(!showNotifications)}
423 |                 className="relative p-1.5 hover:bg-[#1f1f1f] rounded transition-colors text-white"
424 |               >
425 |                 <Bell size={16} className="text-[#bbbbbb] hover:text-white" />
426 |                 <span className="absolute top-0 right-0 w-2.5 h-2.5 bg-[#e22718] rounded-full border-2 border-black" />
427 |               </button>
428 | 
429 |               {/* NOTIFICATIONS INTERACTIVE DROPDOWN */}
430 |               {showNotifications && (
