432 |                   <div className="flex justify-between items-center pb-2 border-b border-[#333]">
433 |                     <div className="flex items-center gap-1.5 font-bold uppercase text-xs">
434 |                       <Bell size={14} className="text-[#e22718]" />
435 |                       Grid Alerts ({alerts.length})
436 |                     </div>
437 |                     <button onClick={() => setShowNotifications(false)} className="text-[#888] hover:text-white">
438 |                       <X size={14} />
439 |                     </button>
440 |                   </div>
441 |                   <div className="max-h-64 overflow-y-auto space-y-2 py-2">
442 |                     {alerts.slice(0, 5).map((a: any, idx: number) => (
443 |                       <div key={idx} className="bg-[#181818] border border-[#333] p-2 hover:bg-[#222]">
444 |                         <div className="flex justify-between items-center mb-1">
445 |                           <span className="font-bold text-white text-[10px]">{a.asset_id}</span>
446 |                           <span className={`px-1 py-0.2 text-[8px] font-extrabold uppercase ${a.severity === "CRITICAL" ? "bg-[#e22718] text-white" : "bg-[#f4b400] text-black"}`}>
447 |                             {a.severity}
448 |                           </span>
449 |                         </div>
450 |                         <div className="text-[9px] text-[#bbb] mb-1.5">{a.fault_type || "High Thermal Stress / DGA Risk"}</div>
451 |                         <div className="flex gap-2">
452 |                           <button
453 |                             onClick={() => {
454 |                               selectAsset(a.asset_id, true);
455 |                               setShowNotifications(false);
456 |                             }}
457 |                             className="bg-[#1c69d4] hover:bg-[#0066b1] text-white text-[8px] font-bold uppercase px-2 py-0.5"
458 |                           >
