466 |                             className="bg-[#333] hover:bg-[#444] text-white text-[8px] font-bold uppercase px-2 py-0.5"
467 |                           >
468 |                             Dispatch Crew
469 |                           </button>
470 |                         </div>
471 |                       </div>
472 |                     ))}
473 |                   </div>
474 |                   <button
475 |                     onClick={() => {
476 |                       setActiveTab("alerts");
477 |                       setShowNotifications(false);
478 |                     }}
479 |                     className="w-full text-center text-[9px] font-bold uppercase text-[#1c69d4] hover:underline pt-2 border-t border-[#333]"
480 |                   >
481 |                     View All Grid Alerts &rarr;
482 |                   </button>
483 |                 </div>
484 |               )}
485 | 
486 |               <div className="flex items-center gap-2">
487 |                 <div className="w-7 h-7 rounded-full bg-[#1c69d4] flex items-center justify-center font-bold text-[10px] uppercase">SLDC</div>
488 |                 <div>
489 |                   <div className="font-bold text-[11px]">System Operator</div>
490 |                   <div className="text-[9px] text-[#bbbbbb]">Gujarat Energy Trans. Corp.</div>
491 |                 </div>
492 |               </div>
493 |             </div>
494 |           </div>
495 |         </header>
496 | 
497 |         {/* DISPATCH / DISPATCH STATUS BANNER */}
498 |         {dispatchNotice && (
499 |           <div className="bg-[#1c69d4] text-white px-6 py-2 flex justify-between items-center text-xs font-bold uppercase tracking-wider sticky top-12 z-30 shadow-lg">
500 |             <div className="flex items-center gap-2">

