Contents of file frontend/src/components/GridMap.tsx:

1 | "use client";
2 | 
3 | import React, { useEffect, useRef, useState } from "react";
4 | import "leaflet/dist/leaflet.css";
5 | 
6 | const MAPTILER_KEY = "CRFoY3RXgAloQLarTcRL";
7 | 
8 | // Tile Styles
9 | const TILE_STYLES: Record<string, { name: string; url: string; subdomains?: string[] }> = {
10 |   dataviz: {
11 |     name: "Dark SCADA",
12 |     url: `https://api.maptiler.com/maps/dataviz-dark/256/{z}/{x}/{y}.png?key=${MAPTILER_KEY}`,
13 |   },
14 |   hybrid: {
15 |     name: "Satellite Hybrid",
16 |     url: `https://api.maptiler.com/maps/hybrid/256/{z}/{x}/{y}.jpg?key=${MAPTILER_KEY}`,
17 |   },
18 |   streets: {
19 |     name: "Highways & Grid",
20 |     url: `https://api.maptiler.com/maps/streets-v2-dark/256/{z}/{x}/{y}.png?key=${MAPTILER_KEY}`,
21 |   },
22 | };
23 | 
24 | const riskColor: Record<string, string> = {
25 |   CRITICAL: "#e22718",
26 |   HIGH: "#f48c06",
27 |   MEDIUM: "#f4b400",
28 |   LOW: "#0fa336",
29 | };
30 | 
31 | interface GridMapProps {
32 |   markers: Array<{
33 |     asset_id: string;
34 |     asset_type?: string;
35 |     name?: string;
36 |     latitude: number;
37 |     longitude: number;
38 |     risk_level: string;
39 |     overall_risk_score?: number;
40 |     customers_served?: number;
41 |     voltage_kv?: number;
42 |     capacity_mva?: number;
43 |     district?: string;
44 |   }>;
45 |   selectedAssetId?: string;
46 |   onSelectAsset?: (assetId: string) => void;
47 | }
48 | 
49 | export default function GridMap({
50 |   markers = [],
51 |   selectedAssetId,
52 |   onSelectAsset,
53 | }: GridMapProps) {
54 |   const containerRef = useRef<HTMLDivElement>(null);
55 |   const mapInstanceRef = useRef<any>(null);
56 |   const markersLayerRef = useRef<any>(null);
57 |   const linesLayerRef = useRef<any>(null);
58 |   const tileLayerRef = useRef<any>(null);
59 |   const [currentStyle, setCurrentStyle] = useState<string>("dataviz");
60 |   const [showPowerLines, setShowPowerLines] = useState<boolean>(true);
61 | 
62 |   const onSelectRef = useRef(onSelectAsset);
63 |   onSelectRef.current = onSelectAsset;
64 | 
65 |   const selectedRef = useRef(selectedAssetId);
66 |   selectedRef.current = selectedAssetId;
67 | 
68 |   // Initialize Map safely (fixing "Map container is already initialized" error)
69 |   useEffect(() => {
70 |     if (!containerRef.current) return;
71 | 
72 |     // Destroy existing leaflet instance attached to DOM element
73 |     if (mapInstanceRef.current) {
74 |       mapInstanceRef.current.remove();
75 |       mapInstanceRef.current = null;
76 |     }
77 | 
78 |     if ((containerRef.current as any)._leaflet_id != null) {
79 |       (containerRef.current as any)._leaflet_id = null;
80 |     }
81 | 
82 |     let isMounted = true;
83 | 
84 |     import("leaflet").then((leafletModule) => {
85 |       if (!isMounted || !containerRef.current) return;
86 |       const L = leafletModule.default || leafletModule;
87 | 
88 |       delete (L.Icon.Default.prototype as any)._getIconUrl;
89 | 
90 |       const map = L.map(containerRef.current, {
91 |         center: [22.8, 71.5], // Gujarat Geographical Center
92 |         zoom: 7.5,
93 |         minZoom: 6,
94 |         maxZoom: 18,
95 |         zoomControl: true,
96 |         attributionControl: false,
97 |       });
98 | 
99 |       mapInstanceRef.current = map;
100 | 
101 |       // Base Tile Layer with Carto Dark fallback
102 |       const baseTile = L.tileLayer(TILE_STYLES[currentStyle].url, {
103 |         maxZoom: 19,
104 |         tileSize: 256,
105 |         errorTileUrl: "https://a.basemaps.cartocdn.com/dark_all/0/0/0.png",
106 |       }).addTo(map);
107 | 
108 |       tileLayerRef.current = baseTile;
109 | 
110 |       baseTile.on("tileerror", () => {
111 |         baseTile.setUrl("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png");
112 |       });
113 | 
114 |       // Layer for Transmission Lines
115 |       const linesGroup = L.layerGroup().addTo(map);
116 |       linesLayerRef.current = linesGroup;
117 | 
118 |       // Layer for Equipment Markers
119 |       const markersGroup = L.layerGroup().addTo(map);
120 |       markersLayerRef.current = markersGroup;
121 | 
122 |       // Render assets and interconnecting transmission grid lines
123 |       renderMapContent(L, markersGroup, linesGroup, markers, selectedRef.current, showPowerLines);
124 | 
125 |       // Invalidate layout dimensions safely
126 |       setTimeout(() => {
127 |         if (mapInstanceRef.current) mapInstanceRef.current.invalidateSize();
128 |       }, 250);
129 | 
130 |       const handleResize = () => {
131 |         if (mapInstanceRef.current) mapInstanceRef.current.invalidateSize();
132 |       };
133 |       window.addEventListener("resize", handleResize);
134 |     });
135 | 
136 |     return () => {
137 |       isMounted = false;
138 |       if (mapInstanceRef.current) {
139 |         mapInstanceRef.current.remove();
140 |         mapInstanceRef.current = null;
141 |       }
142 |       if (containerRef.current) {
143 |         (containerRef.current as any)._leaflet_id = null;
144 |       }
145 |     };
146 |   }, []);
147 | 
148 |   // Switch Tile Theme (Satellite Hybrid vs Dark SCADA)
149 |   const changeTileStyle = (styleKey: string) => {
150 |     setCurrentStyle(styleKey);
151 |     if (tileLayerRef.current) {
152 |       tileLayerRef.current.setUrl(TILE_STYLES[styleKey].url);
153 |     }
154 |   };
155 | 
156 |   // Render Markers & Grid Interconnect Lines
157 |   const renderMapContent = (
158 |     L: any,
159 |     markersGroup: any,
160 |     linesGroup: any,
161 |     items: typeof markers,
162 |     selectedId?: string,
163 |     drawLines = true
164 |   ) => {
165 |     if (!markersGroup || !linesGroup) return;
166 |     markersGroup.clearLayers();
167 |     linesGroup.clearLayers();
168 | 
169 |     if (!items || items.length === 0) return;
170 | 
171 |     // 1. Separate Substations / Power Plants for Transmission Interconnects
172 |     const substations = items.filter(
173 |       (a) =>
174 |         a.asset_type === "substation" ||
175 |         a.asset_type === "power_plant" ||
176 |         a.asset_id.startsWith("SS-") ||
177 |         a.asset_id.startsWith("PP-")
178 |     );
179 | 
180 |     // 2. Draw High Voltage Grid Transmission Lines between Substations
181 |     if (drawLines && substations.length > 1) {
182 |       // Connect geographically nearest substations to simulate GETCO 400kV / 220kV Grid
183 |       for (let i = 0; i < substations.length; i++) {
184 |         const s1 = substations[i];
185 |         if (!s1.latitude || !s1.longitude) continue;
186 | 
187 |         // Find 2 nearest neighbors
188 |         const neighbors = substations
189 |           .filter((_, idx) => idx !== i)
190 |           .map((s2) => ({
191 |             s2,
192 |             dist: Math.hypot(s1.latitude - s2.latitude, s1.longitude - s2.longitude),
193 |           }))
194 |           .sort((a, b) => a.dist - b.dist)
195 |           .slice(0, 2);
196 | 
197 |         neighbors.forEach(({ s2, dist }) => {
198 |           if (dist < 1.8) {
199 |             // Draw transmission line
200 |             const line = L.polyline(
201 |               [
202 |                 [s1.latitude, s1.longitude],
203 |                 [s2.latitude, s2.longitude],
204 |               ],
205 |               {
206 |                 color: "#1c69d4",
207 |                 weight: 1.5,
208 |                 opacity: 0.45,
209 |                 dashArray: "4, 6",
210 |               }
211 |             );
212 |             linesGroup.addLayer(line);
213 |           }
214 |         });
215 |       }
216 |     }
217 | 
218 |     // 3. Render Custom Industrial Markers
219 |     items.forEach((asset) => {
220 |       if (!asset.latitude || !asset.longitude) return;
221 | 
222 |       const risk = (asset.risk_level || "MEDIUM").toUpperCase();
223 |       const color = riskColor[risk] || riskColor.MEDIUM;
224 |       const isSelected = selectedId === asset.asset_id;
225 |       const isPowerPlant = asset.asset_type === "power_plant" || asset.asset_id.startsWith("PP-");
226 |       const isSubstation = asset.asset_type === "substation" || asset.asset_id.startsWith("SS-");
227 |       const isCritical = risk === "CRITICAL";
228 | 
229 |       // Distinct geometry: Power Plant (large star/hex), Substation (diamond), Transformer (circle)
230 |       let shapeStyles = "border-radius: 50%;";
231 |       let size = isSelected ? 20 : 11;
232 |       let symbolText = "";
233 | 
234 |       if (isPowerPlant) {
235 |         shapeStyles = "border-radius: 3px; transform: rotate(0deg);";
236 |         size = isSelected ? 24 : 16;
237 |         symbolText = "⚡";
238 |       } else if (isSubstation) {
239 |         shapeStyles = "border-radius: 2px; transform: rotate(45deg);";
240 |         size = isSelected ? 20 : 13;
241 |       }
242 | 
243 |       const html = `
244 |         <div class="custom-grid-marker ${isCritical ? "marker-critical-pulse" : ""} ${isSelected ? "marker-selected" : ""}" 
245 |              style="width: ${size}px; height: ${size}px; background: ${color}; ${shapeStyles} 
246 |                     border: ${isSelected ? "3px solid #ffffff" : "2px solid rgba(255,255,255,0.9)"}; 
247 |                     box-shadow: 0 0 ${isSelected ? "18px" : isPowerPlant ? "12px" : "6px"} ${color}; 
248 |                     display: flex; align-items: center; justify-content: center; font-size: 9px; cursor: pointer;">
249 |           ${symbolText}
250 |         </div>
251 |       `;
252 | 
253 |       const icon = L.divIcon({
254 |         className: "leaflet-grid-div-icon",
255 |         html: html,
256 |         iconSize: [size, size],
257 |         iconAnchor: [size / 2, size / 2],
258 |       });
259 | 
260 |       const marker = L.marker([asset.latitude, asset.longitude], { icon: icon });
261 | 
262 |       // Technical Inspector Popup
263 |       const popupHtml = `
264 |         <div style="background: #0d0d0d; color: #fff; padding: 12px 14px; font-family: Inter, sans-serif; font-size: 11px; border: 1px solid #3c3c3c; min-width: 170px; box-shadow: 0 12px 32px rgba(0,0,0,0.9);">
265 |           <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 2px;">
266 |             <span style="font-weight: 800; font-size: 13px; color: #fff; letter-spacing: 0.04em;">${asset.asset_id}</span>
267 |             <span style="background: ${color}; color: #fff; font-weight: 800; font-size: 8px; padding: 2px 5px; text-transform: uppercase;">${risk}</span>
268 |           </div>
269 |           <div style="color: #888; font-size: 9px; text-transform: uppercase; margin-bottom: 6px;">
270 |             ${isPowerPlant ? "🏭 Power Generation Station" : isSubstation ? "⚡ GETCO Substation" : "🔌 Distribution Transformer"}
271 |           </div>
272 |           <div style="color: #bbb; font-size: 10px; margin-bottom: 6px; border-bottom: 1px solid #222; padding-bottom: 4px;">
273 |             ${asset.name || "Gujarat Power Grid"} &bull; ${asset.district || "Gujarat"}
274 |           </div>
275 |           <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 4px; font-size: 9px; color: #aaa; margin-bottom: 6px;">
276 |             <div>Capacity: <b style="color:#fff">${asset.capacity_mva || 40} MVA</b></div>
277 |             <div>Voltage: <b style="color:#fff">${asset.voltage_kv || 66} kV</b></div>
278 |             <div>Risk Score: <b style="color:${color}">${Math.round(asset.overall_risk_score || 50)}%</b></div>
279 |             <div>Customers: <b style="color:#fff">${(asset.customers_served || 0).toLocaleString()}</b></div>
280 |           </div>
281 |           <div style="font-size: 8px; color: #1c69d4; font-weight: 800; text-transform: uppercase; text-align: center; border-top: 1px solid #222; padding-top: 5px; cursor: pointer;">
282 |             Click to focus & inspect &rarr;
283 |           </div>
284 |         </div>
285 |       `;
286 | 
287 |       marker.bindPopup(popupHtml, {
288 |         offset: [0, -size / 2],
289 |         closeButton: false,
290 |         className: "custom-leaflet-popup",
291 |       });
292 | 
293 |       marker.on("click", () => {
294 |         lastCenteredAssetIdRef.current = null;
295 |         if (onSelectRef.current) {
296 |           onSelectRef.current(asset.asset_id);
297 |         }
298 |       });
299 | 
300 |       marker.on("popupopen", (e: any) => {
301 |         const popupNode = e.popup?.getElement();
302 |         if (popupNode) {
303 |           popupNode.style.cursor = "pointer";
304 |           popupNode.onclick = (evt: MouseEvent) => {
305 |             evt.stopPropagation();
306 |             lastCenteredAssetIdRef.current = null;
307 |             if (onSelectRef.current) {
308 |               onSelectRef.current(asset.asset_id);
309 |             }
310 |           };
311 |         }
312 |       });
313 | 
314 |       marker.on("mouseover", function (this: any) {
315 |         this.openPopup();
316 |       });
317 | 
318 |       markersGroup.addLayer(marker);
319 |     });
320 |   };
321 | 
322 |   const lastCenteredAssetIdRef = useRef<string | null>(null);
323 | 
324 |   // Update markers when props change and fly to selected asset ONLY when selection changes
325 |   useEffect(() => {
326 |     if (!mapInstanceRef.current || !markersLayerRef.current) return;
327 |     import("leaflet").then((leafletModule) => {
328 |       const L = leafletModule.default || leafletModule;
329 |       renderMapContent(L, markersLayerRef.current, linesLayerRef.current, markers, selectedAssetId, showPowerLines);
330 | 
331 |       if (
332 |         selectedAssetId &&
333 |         selectedAssetId !== lastCenteredAssetIdRef.current &&
334 |         markers &&
335 |         markers.length > 0
336 |       ) {
337 |         lastCenteredAssetIdRef.current = selectedAssetId;
338 |         const target = markers.find((m) => m.asset_id === selectedAssetId);
339 |         if (target && target.latitude && target.longitude) {
340 |           mapInstanceRef.current.flyTo([target.latitude, target.longitude], 11.5, {
341 |             animate: true,
342 |             duration: 1.2,
343 |           });
344 |         }
345 |       }
346 |     });
347 |   }, [markers, selectedAssetId, showPowerLines]);
348 | 
349 |   return (
350 |     <div className="w-full h-full relative bg-[#0a0a0a] overflow-hidden" style={{ minHeight: "100%", width: "100%" }}>
351 |       <style jsx global>{`
352 |         @keyframes criticalPulse {
353 |           0% {
354 |             box-shadow: 0 0 0 0 rgba(226, 39, 24, 0.9), 0 0 8px #e22718;
355 |           }
356 |           70% {
357 |             box-shadow: 0 0 0 14px rgba(226, 39, 24, 0), 0 0 12px #e22718;
358 |           }
359 |           100% {
360 |             box-shadow: 0 0 0 0 rgba(226, 39, 24, 0), 0 0 8px #e22718;
361 |           }
362 |         }
363 |         .marker-critical-pulse {
364 |           animation: criticalPulse 1.8s infinite !important;
365 |         }
366 |         .marker-selected {
367 |           transform: scale(1.4) !important;
368 |           z-index: 1000 !important;
369 |         }
370 |         .leaflet-grid-div-icon {
371 |           background: transparent !important;
372 |           border: none !important;
373 |         }
374 |         .custom-leaflet-popup .leaflet-popup-content-wrapper {
375 |           background: transparent !important;
376 |           padding: 0 !important;
377 |           border-radius: 0 !important;
378 |           box-shadow: none !important;
379 |         }
380 |         .custom-leaflet-popup .leaflet-popup-content {
381 |           margin: 0 !important;
382 |           line-height: normal !important;
383 |         }
384 |         .custom-leaflet-popup .leaflet-popup-tip {
385 |           background: #0d0d0d !important;
386 |           border: 1px solid #3c3c3c !important;
