            >
              {riskLvl}
            </span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={load}
            className="flex items-center gap-1 text-[#888] hover:text-white text-[10px] font-bold uppercase"
          >
            <RefreshCw size={12} />
            Refresh
          </button>
          <span className="text-[9px] text-[#444]">
