      console.error("Data load failed:", e);
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  }, [selectAsset]);

  // Tab-specific lazy fetching
  useEffect(() => {
    if (activeTab === "assets" && assetsList.length === 0) {
