              <Send size={14} className="animate-pulse" />
              {dispatchNotice}
            </div>
            <button onClick={() => setDispatchNotice(null)} className="text-white hover:opacity-75">
              <X size={14} />
            </button>
          </div>
        )}

        {/* VIEW 1: MAIN DASHBOARD */}
        {activeTab === "dashboard" && (
