      <p className="text-[9px] text-[#888] mb-2 line-clamp-2">{desc}</p>
      <button
        onClick={onAction}
        className={`w-full text-[9px] font-bold uppercase py-1 ${
          btnOutline ? "border border-[#333] text-white hover:bg-[#222]" : "bg-[#1c69d4] text-white hover:bg-[#0066b1]"
        }`}
      >
        {btn}
      </button>
    </div>
  );
}

