                </button>
                <button
                  type="submit"
                  className="px-4 py-1.5 bg-[#1c69d4] hover:bg-[#0066b1] text-white font-bold uppercase text-[9px]"
                >
                  Create Work Order
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
