                      <input type="range" min="5" max="250" value={simHydrogen} onChange={(e) => setSimHydrogen(Number(e.target.value))} className="w-full accent-[#1c69d4]" />
                    </div>
                  </div>
                </div>

                <button
                  onClick={() => handleSimulate()}
