    if (filterType === "TRANSFORMER") return m.asset_type === "transformer" || m.asset_id?.startsWith("TR-");
    return true;
  });

  const currentWeather = weather.find((w: any) => w.district === "Ahmedabad") || weather[0];

  const filteredSensors = sensorStream.filter((s) => {
