// Action Item Component
function ActionItem({ icon, type, title, desc, priority, btn, btnOutline, onAction }: any) {
  return (
    <div className={`bg-[#111] border ${type === "critical" ? "border-[#e22718]" : "border-[#333]"} p-2.5 text-[10px]`}>
