                      assetTypeFilter === af.id ? "bg-[#1c69d4] border-[#1c69d4] text-white" : "bg-[#111] border-[#333] text-[#888] hover:text-white"
                    }`}
                  >
                    {af.label}
                  </button>
                ))}
              </div>
            </div>

