                            Map
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* VIEW 4: SCADA SENSORS MONITORING STREAM */}
        {activeTab === "sensors" && (
          <div className="p-5 space-y-4">
            <div className="flex justify-between items-center">
              <div>
                <h1 className="text-lg font-bold uppercase">Live SCADA Sensor Telemetry Stream</h1>
