                      </td>
                      <td className={`p-2.5 text-right font-mono ${s.oil_temperature > 80 ? "text-[#e22718] font-bold" : "text-[#bbb]"}`}>
                        {s.oil_temperature}°C
                      </td>
                      <td className={`p-2.5 text-right font-mono ${s.load_percent > 105 ? "text-[#e22718] font-bold" : "text-white"}`}>
