                            <td className="py-2.5 px-1 text-[#888]">{index + 1}</td>
                            <td className="py-2.5 font-bold text-white">{asset.asset_id}</td>
                            <td className="py-2.5 text-center">{pBadge}</td>
                            <td className="py-2.5 text-center font-bold text-white">
