                                <span className="font-bold text-[9px]" style={{ color: impactColor }}>{Math.round(impactScore)}</span>
                              </div>
                            </td>
                            <td className="py-2.5 text-right font-mono text-[#bbb]">{(asset.customers_served || 0).toLocaleString()}</td>
