                          <button
                            onClick={() => router.push(`/transformers/${a.asset_id}`)}
                            className="bg-[#1c69d4] text-white px-2.5 py-1 font-bold uppercase text-[9px] hover:bg-[#0066b1]"
                          >
                            Inspect
                          </button>
                          <button
                            onClick={() => selectAsset(a.asset_id, true)}
                            className="bg-[#222] border border-[#444] text-white px-2.5 py-1 font-bold uppercase text-[9px] hover:bg-[#333]"
                          >
                            Map
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* VIEW 4: SCADA SENSORS MONITORING STREAM */}
        {activeTab === "sensors" && (
          <div className="p-5 space-y-4">
