                className="bg-[#1c69d4] hover:bg-[#0066b1] text-white px-3 py-1.5 text-[10px] font-bold uppercase flex items-center gap-1.5"
              >
                <Plus size={14} />
                Log New Work Order
              </button>
            </div>

            {/* MAINTENANCE KPI SUMMARY */}
            <div className="grid grid-cols-3 gap-3">
