        {/* VIEW 7: CREW PLANNING */}
        {activeTab === "crews" && (
          <div className="p-5 space-y-4">
            <div className="flex justify-between items-center">
              <div>
                <h1 className="text-lg font-bold uppercase">Field Crew Positioning & Dispatch</h1>
