function MetricCard({ title, value, icon, subtext, alert, warning }: any) {
  return (
    <div className={`bg-[#1a1a1a] border ${alert ? "border-[#e22718]" : warning ? "border-[#f48c06]" : "border-[#3c3c3c]"} p-3 flex flex-col justify-between`}>
